from __future__ import annotations


class LoginGuard:
    """
    Consecutive-failure throttling per account.

    Rule: An account is locked once it reaches 100 consecutive failed attempts,
    not before. A successful authentication resets the consecutive-failure count.
    """

    _MAX_CONSECUTIVE_FAILURES = 100

    def __init__(self) -> None:
        self._failures: dict[str, int] = {}

    def failed(self, account: str) -> None:
        """Record a consecutive failed password attempt for the given account."""
        if not isinstance(account, str):
            raise TypeError("account must be a string")
        self._failures[account] = self._failures.get(account, 0) + 1

    def succeeded(self, account: str) -> None:
        """Reset consecutive-failure count after a successful authentication."""
        if not isinstance(account, str):
            raise TypeError("account must be a string")
        self._failures[account] = 0

    def locked(self, account: str) -> bool:
        """Return True iff the account has reached the lock threshold."""
        if not isinstance(account, str):
            raise TypeError("account must be a string")
        return self._failures.get(account, 0) >= self._MAX_CONSECUTIVE_FAILURES
